delete from BOK_CHECK_LOG where CHECK_TYPE='手工检查' and CHECK_DATE=STR_TO_DATE(#{sysDate,jdbcType=VARCHAR},'%Y-%m-%d')
and BOOKSET_ID in
#{item}

mapper.select:
SELECT MAX(BOOKSET_ID) booksetId, DATE_FORMAT(CHECK_DATE,'%Y-%m-%d') bookPDate, CAST(LOG_INFO AS CHAR) logInfo, DATE_FORMAT(CHECK_DATE,'%Y-%m-%d') pageDate FROM BOK_CHECK_LOG WHERE CHECK_TYPE='手工检查' AND DATE_FORMAT(CHECK_DATE,'%Y-%m-%d')=#{endDate}
and BOOKSET_ID in
#{item}
GROUP BY BOOKSET_ID, CHECK_DATE,CAST(LOG_INFO AS CHAR) ORDER BY BOOKSET_ID select count(1) from BOK_CHECK_LOG where CHECK_TYPE='手工检查' and CHECK_DATE=#{sysDate}
and BOOKSET_ID in
#{item}
